 function priceOf(item){return state.prices[item.id]??item.price}
 function render(){document.querySelector('#day').textContent=String(state.day).padStart(2,'0');document.querySelector('#cash').textContent=money(state.cash);document.querySelector('#revenue').textContent=money(state.revenue);document.querySelector('#traffic').textContent=state.traffic;document.querySelector('#happiness').textContent=state.happiness+'%';document.querySelector('#locations').textContent=state.stores.length;document.querySelector('#locSub').textContent=state.stores.map(x=>storeDefs[x].name).join(' · ');document.querySelector('#mapTitle').textContent=storeDefs[state.active].name;document.querySelector('#mapType').textContent=storeDefs[state.active].map;document.querySelector('#shelfCount').textContent=state.shelves+' shelves';document.querySelector('#subtitle').textContent=state.played?`Day ${state.day} at ${storeDefs[state.active].name} — make it a good one.`:'Your neighborhood market is ready for its first customers.';document.querySelector('#revSub').textContent=state.revenue?`Today's takings · ${state.traffic} lovely customers`:'Store is ready to open';document.querySelector('#happySub').textContent=state.happiness>75?'A lovely start to the day':state.happiness>50?'Some prices could use a second look':'Customers are looking for better value';document.querySelector('#upgradeCost').textContent='Add shelf · '+money(450+Math.max(0,state.shelves-4)*250);document.querySelector('#upgradeButton').disabled=state.cash<450+Math.max(0,state.shelves-4)*250;document.querySelector('#openButton').querySelector('strong').innerHTML=state.played?'☀ &nbsp; Open next day':'☀ &nbsp; Open for the day';document.querySelector('#goalProgress').textContent=`${Math.min(state.daysTraded,3)} / 3 days`;document.querySelector('#goalBar').style.width=Math.min(100,state.daysTraded/3*100)+'%';document.querySelector('#goalName').textContent=state.daysTraded>=3?'First-week grant earned!':'Build your first week';document.querySelector('#goalText').textContent=state.daysTraded>=3?'You earned the $500 local-business grant. Keep growing!':'Trade for 3 days to earn a $500 local-business grant.';renderProducts();renderMap();renderFeed();save();}
 function renderProducts(){const list=document.querySelector('#productList');const stores=tab===0?[state.active]:state.stores;list.innerHTML=stores.flatMap(type=>state.inventory[type].map(item=>{const p=priceOf(item);let name=tab?storeDefs[type].emoji+' '+item.name:item.name;return `<div class="item"><div class="item-icon">${item.icon}</div><div><div class="item-name">${name}</div><div class="item-meta">Cost ${money(item.cost)} · ${type==='market'?'Grocery':type==='electronics'?'Electronics':'Clothing'}</div></div><div class="item-tools"><div class="price">${money(p)}</div><div class="qty">${item.qty} in stock</div><div class="stepper"><button data-price="${item.id}" data-delta="-1">−</button><button data-price="${item.id}" data-delta="1">+</button><button class="purchase" data-buy="${item.id}" data-type="${type}" ${state.cash<item.cost?'disabled':''}>Restock</button></div></div></div>`}).join('')).join('');let inv=stores.flatMap(t=>state.inventory[t]);document.querySelector('#stockValue').textContent='Stock value '+money(inv.reduce((sum,i)=>sum+i.qty*i.cost,0));list.querySelectorAll('[data-price]').forEach(b=>b.onclick=()=>{const item=stores.flatMap(t=>state.inventory[t]).find(x=>x.id===b.dataset.price);state.prices[item.id]=Math.max(1,priceOf(item)+Number(b.dataset.delta));render()});list.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.type,b.dataset.buy));}
 function buy(type,id){const item=state.inventory[type].find(x=>x.id===id);const qty=5;const cost=item.cost*qty;if(state.cash<cost){toast('Not enough cash for this order');return}state.cash-=cost;item.qty+=qty;note(`Restocked ${qty} × ${item.name} for ${money(cost)}.`,'📦');render();toast('Supplier order delivered!')}
-function renderMap(){const map=document.querySelector('#storeMap');map.querySelectorAll('.shelf').forEach(x=>x.remove());const items=state.inventory[state.active]||[];const count=Math.min(6,Math.max(3,state.shelves));const locs=[['horizontal','left:12%;top:28%'],['horizontal','left:12%;top:51%'],['vertical','left:54%;top:28%'],['horizontal','left:12%;top:74%'],['vertical','left:68%;top:28%'],['horizontal','left:57%;top:77%']];for(let i=0;i<count;i++){const div=document.createElement('div');div.className='shelf '+(i===2||i===4?'vertical':'horizontal');div.style.cssText=locs[i][1];const item=items[i%items.length];div.innerHTML=`<span class="shelf-name">${item?item.name.split(' ')[0].toUpperCase():'STOCK'}</span>${Array.from({length:5},(_,k)=>`<i class="product-dot" style="opacity:${item?.qty>k?1:.2}"></i>`).join('')}`;map.append(div)}document.querySelector('#openTag').textContent='● OPEN';}
+function renderMap(){const map=document.querySelector('#storeMap');map.querySelectorAll('.shelf,.customer').forEach(x=>x.remove());const shoppers=['🧍🏻','🧍🏽‍♀️','🧍🏼‍♂️'];shoppers.slice(0,Math.min(3,Math.max(1,state.traffic?Math.ceil(state.traffic/7):2))).forEach((emoji,i)=>{const person=document.createElement('span');person.className='customer';person.textContent=emoji;person.style.cssText=`left:${35+i*13}%;top:${31+(i%2)*30}%`;map.append(person)});const items=state.inventory[state.active]||[];const count=Math.min(6,Math.max(3,state.shelves));const locs=[['horizontal','left:12%;top:28%'],['horizontal','left:12%;top:51%'],['vertical','left:54%;top:28%'],['horizontal','left:12%;top:74%'],['vertical','left:68%;top:28%'],['horizontal','left:57%;top:77%']];for(let i=0;i<count;i++){const div=document.createElement('div');div.className='shelf '+(i===2||i===4?'vertical':'horizontal');div.style.cssText=locs[i][1];const item=items[i%items.length];div.innerHTML=`<span class="shelf-name">${item?item.name.split(' ')[0].toUpperCase():'STOCK'}</span>${Array.from({length:5},(_,k)=>`<i class="product-dot" style="opacity:${item?.qty>k?1:.2}"></i>`).join('')}`;map.append(div)}document.querySelector('#openTag').textContent='● OPEN';}
 function renderFeed(){document.querySelector('#feed').innerHTML=state.events.slice(0,4).map(e=>`<div class="feed-row"><span class="feed-icon">${e.icon}</span><span>${e.text}</span><small>${e.time}</small></div>`).join('')}
 function endDay(){let totalRev=0,totalSold=0,totalTraffic=0,score=0,scored=0;for(const type of state.stores){const items=state.inventory[type];let foot=0;for(const item of items){const p=priceOf(item),ratio=p/item.price;const pricing=Math.max(.15,1-Math.max(0,ratio-1)*.8-Math.max(0,1-ratio)*.1);const want=Math.round(item.demand*pricing*(.75+Math.random()*.55)*(type===state.active?1:.72));const sold=Math.min(item.qty,want);item.qty-=sold;foot+=sold;totalSold+=sold;totalRev+=sold*p;score+=Math.min(1.15,pricing*1.08);scored++}totalTraffic+=Math.max(3,Math.round(foot*1.25));}state.cash+=totalRev;state.revenue=Math.round(totalRev);state.traffic=totalTraffic;state.happiness=Math.max(30,Math.min(99,Math.round(score/scored*78+Math.random()*8)));state.day++;state.daysTraded++;state.played=true;note(`You welcomed ${totalTraffic} customers and rang up ${money(totalRev)} in sales.`,'🧾');if(state.daysTraded===3){state.cash+=500;note('Your first-week grant of $500 has arrived!','🎉');toast('Milestone reached — $500 grant earned!')}else toast(`Day closed · ${money(totalRev)} sales`);state.revenue=state.revenue;render();}
 function upgrade(){const cost=450+Math.max(0,state.shelves-4)*250;if(state.cash<cost){toast('Not enough cash for that upgrade');return}state.cash-=cost;state.shelves++;note(`Added a beautiful new shelf to ${storeDefs[state.active].name}.`,'🛠');render();toast('Store upgraded! More room to grow.')}
 function openModal(){document.querySelector('#modal').classList.add('show');document.querySelector('#storeOptions').innerHTML=['electronics','clothing'].map(type=>{const d=storeDefs[type],owned=state.stores.includes(type);return `<div class="store-option"><div class="big">${d.emoji}</div><h3>${d.name}</h3><p>${d.map}. Fresh customers, fresh opportunity.</p><div class="cost">${owned?'ALREADY OPEN':money(d.cost)}</div><button data-store="${type}" ${owned||state.cash<d.cost?'disabled':''}>${owned?'Owned':`Buy location`}</button></div>`}).join('');document.querySelectorAll('[data-store]').forEach(b=>b.onclick=()=>acquire(b.dataset.store));}
